#!/usr/bin/env python3
"""Clickable review of the restored original menu, using actual native captures."""
import base64,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
images={p.stem:'data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode() for p in (ROOT/'preview').glob('*.png')}
html='''<!doctype html><html lang="pl"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Polish Fighters • klasyczne menu</title><style>*{box-sizing:border-box}body{margin:0;padding:18px;background:#070e30;color:#c5cef4;font:14px system-ui;display:flex;align-items:center;flex-direction:column}header,footer{width:min(100%,1000px);display:flex;justify-content:space-between;gap:12px;margin:12px 0}header{align-items:center}button{cursor:pointer;font:inherit}header button,footer button,dialog button{padding:8px 14px;background:#14245f;border:1px solid #4b60a0;color:#fff}main{width:min(100%,1000px);border:1px solid #314998;position:relative;aspect-ratio:794/550}main.phone{width:min(100%,820px)}img{width:100%;height:100%;display:block}.hot{position:absolute;background:transparent;border:0;color:transparent}.hot:hover,.hot:focus-visible{outline:2px solid #ffe340;outline-offset:-2px;background:#ffffff14}dialog{background:#102050;border:2px solid #526fb7;color:white;max-width:90vw;width:480px;padding:25px}dialog::backdrop{background:#000a}dialog p{line-height:1.7}small{font-size:12px;color:#99aadb}footer{font-size:12px;align-items:center}@media(max-width:600px){body{padding:5px}header{font-size:11px;flex-wrap:wrap}footer{flex-wrap:wrap}}</style><header><span>POLISH FIGHTERS 0.6<br><small>Oryginalne menu LF2 + klasyczne dodatki</small></span><div><button id="windows">Windows</button> <button id="android">Android</button></div></header><main id="view"><img id="image" alt="Oryginalne menu LF2"><div id="buttons"></div></main><footer><span>Podgląd ekranów z silnika. Nie uruchamia gry ani logowania.</span><div><button id="fight">LeumasEX</button> <button id="tiger">Tiger</button> <button id="room">Lobby 8 graczy</button></div></footer><dialog id="dialog"><h2 id="title"></h2><p id="message"></p><button id="close">Powrót</button></dialog><script>const screens=__IMAGES__;const labels={classic:'Oryginalne menu LF2',extras:'Dodatki Polish Fighters',maps:'Mapy',packs:'Pakiety',connection:'Połączenia',account:'Konto'};let page='classic';let selected='HK Coliseum';const area=document.getElementById('buttons');const dialog=document.getElementById('dialog');function notice(title,text){document.getElementById('title').textContent=title;document.getElementById('message').textContent=text;dialog.showModal()}function hit(label,x,y,w,h,action){const b=document.createElement('button');b.className='hot';b.setAttribute('aria-label',label);b.title=label;Object.assign(b.style,{left:x/794*100+'%',top:y/550*100+'%',width:w/794*100+'%',height:h/550*100+'%'});b.onclick=action;area.append(b)}function render(next){page=next;area.replaceChildren();document.getElementById('image').src=screens[next==='fight'?'leumas-lf4':next==='tiger'?'tiger-native':next==='room'?'room-eight-native':'classic-'+next];document.getElementById('image').alt=labels[next]||'LeumasEX w walce';if(next==='fight'||next==='tiger'||next==='room'){hit('Powrót do menu',0,0,794,550,()=>render('classic'));return}if(next==='classic'){hit('Game start',270,211,265,29,()=>notice('Rozpocznij grę','W natywnym silniku otwiera wybór trybu i postaci. Ten plik jest podglądem menu.'));hit('Network game',270,246,265,28,()=>render('connection'));hit('Control settings',270,279,265,28,()=>notice('Sterowanie','Natywne menu ustawień klawiatury, pada i dotyku pozostaje dostępne.'));hit('Recording',270,311,265,28,()=>notice('Powtórki','Natywny panel nagrywania działa w silniku.'));hit('Options',270,372,265,28,()=>notice('Opcje','W silniku wybierzesz język i ustawienia obrazu.'));hit('Dodatki',260,414,275,30,()=>render('extras'));return}let list=[];if(next==='extras')list=[['Graj w LF2 Classic',()=>notice('Gra','Wybór postaci jest dostępny w silniku.')],['Wybierz mapę',()=>render('maps')],['Pakiety i postacie',()=>render('packs')],['Połączenia 2-8 urządzeń',()=>render('connection')],['Konto / gość',()=>render('account')],['Ustawienia',()=>notice('Ustawienia','W silniku ten przycisk otwiera klasyczny panel opcji.')],['Powrót do LF2',()=>render('classic')]];if(next==='maps')list=['HK Coliseum','Lion Forest','Stanley Prison','The Great Wall',"Queen’s Island",'Forbidden Tower','Brokeback Clif','CUHK','Tai Hom Village'].map(name=>[name,()=>{selected=name;notice('Wybrano mapę',name+'. W silniku wybór jest zapisywany i przekazywany do pojedynku.')}]).concat([['Graj',()=>notice('Pojedynek','Wybrana arena: '+selected+'. Podgląd nie uruchamia walki.')],['Powrót',()=>render('extras')]]);if(next==='packs')list=['LF2 Classic','LF4 Turbo','Reinforced LF2','LF2 Kate','Naruto','Dragon Ball','One Piece','Bleach','Polish Fighters'].map((name,i)=>[name,()=>notice(name,i===1?'Pakiet danych LF4 Turbo jest dołączony. 32 postacie przeszły testy symulacji na własnym silniku Linux. Weryfikacja wszystkich ciosów i kampanii trwa.':i===0?'Klasyczne dane LF2 są aktywne po dostarczeniu instalatora.':'Ten pakiet nie został jeszcze dodany.')]).concat([['Powrót',()=>render('extras')]]);if(next==='account')list=[['Konto Google',()=>notice('Logowanie niedostępne','Usługa kont nie jest jeszcze podłączona. Nie pobieramy haseł ani e-maili.')],['Konto e-mail',()=>notice('Logowanie niedostępne','Usługa kont nie jest jeszcze podłączona. Gra offline nie wymaga konta.')],['Graj jako gość',()=>render('classic')],['Powrót',()=>render('extras')]];if(next==='connection')list=[['Pokój LAN 2-8',()=>notice('Pokój LAN','Lobby, gotowość i mecz są połączone. Testy 2-8 osobnych procesów Linux przeszły; testy telefonów pozostają do wykonania.')],['Stare połączenie',()=>notice('Dwa urządzenia','Zachowano poprzedni protokół dla dwóch urządzeń.')],['Limit pokoju',()=>notice('Od 2 do 8 urządzeń','Limit określa gospodarz. Można zacząć przy dwóch gotowych uczestnikach, także przy limicie 8.')],['Hotspot / LAN',()=>notice('Bez internetu','Wspólne Wi-Fi lub hotspot i adres IP gospodarza. Bluetooth wymaga osobnej implementacji.')],['Bluetooth',()=>notice('Bluetooth','Niezaimplementowany.')],['Powrót',()=>render('extras')]];list.forEach(([name,action],i)=>hit(name,210,214+i*25,425,22,action))}document.getElementById('close').onclick=()=>dialog.close();document.getElementById('windows').onclick=()=>document.getElementById('view').classList.remove('phone');document.getElementById('android').onclick=()=>document.getElementById('view').classList.add('phone');document.getElementById('fight').onclick=()=>render('fight');document.getElementById('room').onclick=()=>render('room');document.getElementById('tiger').onclick=()=>render('tiger');document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!dialog.open)render('classic');if(e.key==='F10'){e.preventDefault();render('extras')}});render('classic');</script></html>'''
(ROOT/'preview/Polish_Fighters_klasyczne_menu.html').write_text(html.replace('__IMAGES__',json.dumps(images)),encoding='utf-8')
print('Built original-style preview:',len(images),'native captures')
